package com.duoaero;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.webkit.*;import android.view.*;import org.json.*;import java.io.*;import java.util.concurrent.*;
public final class GoogleProgress {
 static String accountKey(String id){try{byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(id.getBytes("UTF-8"));StringBuilder out=new StringBuilder();for(byte b:hash)out.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 final MainActivity host;final WebView web;boolean applying=false,ready=false;String pending="",status="Progress saved on this device";
 GoogleProgress(MainActivity activity){host=activity;web=new WebView(activity);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(this,"InhouseNative");web.setWebViewClient(new WebViewClient(){
  public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest request){Uri u=request.getUrl();if(!u.getScheme().equals("https")||!u.getHost().equals("appassets.androidplatform.net"))return null;String p=u.getPath();if(p==null||!p.startsWith("/shared/")||p.contains(".."))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));try{return new WebResourceResponse(p.endsWith(".js")?"text/javascript":"text/html","UTF-8",host.getAssets().open(p.substring(1)));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}
  public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"appassets.androidplatform.net".equals(r.getUrl().getHost());}
  public void onPageFinished(WebView v,String url){ready=true;if(!pending.isEmpty()){String p=pending;pending="";callback(p);}}
 });web.loadUrl("https://appassets.androidplatform.net/shared/auth-runtime.html");}
 void attach(){if(web.getParent()!=null)((android.view.ViewGroup)web.getParent()).removeView(web);host.root.addView(web,new android.widget.LinearLayout.LayoutParams(1,1));}
 void signIn(){if(!ready){host.attempt(()->{throw new Exception("Google sign-in is loading");});return;}web.evaluateJavascript("DuoAuth.signIn()",null);}
 void changed(){if(!applying&&ready)web.evaluateJavascript("DuoSync.changed()",null);}
 void signOut(){web.evaluateJavascript("DuoSync.signOut()",null);}
 void callback(String raw){if(!ready){pending=raw;return;}web.evaluateJavascript("window.handleInhouseNativeOAuth("+JSONObject.quote(raw)+")",null);}
 <T>T ui(Callable<T> action){FutureTask<T> f=new FutureTask<>(action);host.runOnUiThread(f);try{return f.get(15,TimeUnit.SECONDS);}catch(Exception e){throw new IllegalStateException("Could not access local progress",e);}}
 @JavascriptInterface public void openAuthUrl(String raw){Uri uri=Uri.parse(raw);if(!"https".equals(uri.getScheme())||!"accounts.google.com".equals(uri.getHost()))return;host.runOnUiThread(()->host.startActivity(new Intent(Intent.ACTION_VIEW,uri)));}
 @JavascriptInterface public void onAccount(String id,String label){ui(()->{String current=host.getPreferences(0).getString("google-account","");if(!current.equals(id)){Engine old=host.engine;Engine next=new Engine(host,"progress-google-"+accountKey(id)+".json");if(current.isEmpty()&&!host.getPreferences(0).getBoolean("guest-imported",false)&&next.records().length()==0){next.state=new JSONObject(old.state.toString());next.save();host.getPreferences(0).edit().putBoolean("guest-imported",true).apply();}host.engine=next;host.bindProgress();host.getPreferences(0).edit().putString("google-account",id).putString("google-label",label).apply();if(!host.inQuiz)host.home();}else host.getPreferences(0).edit().putString("google-label",label).apply();return null;});}
 @JavascriptInterface public String readProgress(){return ui(()->host.engine.state.toString());}
 @JavascriptInterface public void applyProgress(String raw){ui(()->{JSONObject incoming=new JSONObject(raw);JSONObject current=host.engine.state;JSONObject records=incoming.optJSONObject("records");if(records!=null){java.util.Iterator<String> keys=records.keys();while(keys.hasNext()){String id=keys.next();JSONObject r=records.optJSONObject(id),old=host.engine.records().optJSONObject(id);if(r!=null&&(old==null||r.optLong("at")>old.optLong("at")))host.engine.records().put(id,r);}}JSONObject ls=incoming.optJSONObject("completedLessons");if(ls!=null){java.util.Iterator<String> keys=ls.keys();while(keys.hasNext()){String id=keys.next();JSONObject r=ls.optJSONObject(id),old=current.getJSONObject("completedLessons").optJSONObject(id);if(r!=null&&(old==null||r.optLong("at")>old.optLong("at")))current.getJSONObject("completedLessons").put(id,r);}}current.put("xp",Math.max(current.optInt("xp"),incoming.optInt("xp")));applying=true;try{host.engine.save();}finally{applying=false;}return null;});}
 @JavascriptInterface public void onStatus(String message){host.runOnUiThread(()->{status=message;if(host.cloudStatus!=null)host.cloudStatus.setText(message);});}
 @JavascriptInterface public void onSignedOut(){ui(()->{host.getPreferences(0).edit().remove("google-account").remove("google-label").apply();host.engine=new Engine(host,"progress-v1.json");host.bindProgress();host.showSignIn();return null;});}
 void close(){web.removeJavascriptInterface("InhouseNative");web.destroy();}
}
